# create predicted grid from source 6x9 pattern replicated across 2x3 panels
pattern=[[0]*9 for _ in range(6)]
for r,c in [(0,2),(0,6),(0,7),(1,2),(2,1),(2,2),(3,1),(3,2),(3,4),(3,6),(5,4)]: pattern[r][c]=9
out=[]
for r in range(13):
    if r==6: out.append([6]*29); continue
    localr=r if r<6 else r-7
    row=[]
    for c in range(29):
        if c in (9,19): row.append(6)
        else: row.append(9 if pattern[localr][c%10 if False else (c if c<9 else c-10 if c<19 else c-20)] else 1)
    out.append(row)
print(out)
